// Puts <rg-account-button> into Squarespace 7.1's header, which has no slot for it:
//   desktop: inside .header-actions--right, just before the Donate button (.header-actions-action--cta);
//   mobile:  in .header-display-mobile, just before the menu (burger) button, since the Donate box is
//            hidden on phones.
// Idempotent: safe to call on every page load and every mercury:load (Squarespace's AJAX navigation).
const SLOT = 'rg-account-slot';

const slotCss = `
.${SLOT} { display: flex; align-items: center; }
/* About the gap between two nav items on the left. None on the right: Squarespace already spaces the
   Donate button from whatever comes before it. */
.header-display-desktop .${SLOT} { margin: 0 0 0 1.85rem; }
.header-display-mobile .${SLOT} { margin-right: .5rem; }
/* Squarespace gives the logo block a fixed calc(100% - 50px) basis that cannot shrink (50px = the menu
   button), so with our button it would push the menu button off-screen: let the logo block give way. */
.header-display-mobile:has(> .${SLOT}) > .header-title-nav-wrapper { flex: 1 1 0; min-width: 0; }
`;

function makeSlot(): HTMLElement {
  const slot = document.createElement('div');
  slot.className = SLOT;
  slot.appendChild(document.createElement('rg-account-button'));
  return slot;
}

/** Returns how many buttons it placed (0 when the page has no Squarespace header or they are already there). */
export function mountHeaderAccountButtons(doc: Document = document): number {
  let placed = 0;
  const desktopActions = doc.querySelector('.header-display-desktop .header-actions--right');
  if (desktopActions && !desktopActions.querySelector(`.${SLOT}`)) {
    desktopActions.insertBefore(makeSlot(), desktopActions.querySelector('.header-actions-action--cta'));
    placed++;
  }
  const mobile = doc.querySelector('.header-display-mobile');
  const burger = mobile?.querySelector(':scope > .header-burger');
  if (mobile && burger && !mobile.querySelector(`.${SLOT}`)) {
    mobile.insertBefore(makeSlot(), burger);
    placed++;
  }
  if (placed && !doc.getElementById('rg-account-slot-css')) {
    const style = doc.createElement('style');
    style.id = 'rg-account-slot-css';
    style.textContent = slotCss;
    doc.head.appendChild(style);
  }
  return placed;
}
